(async () => {
	// Valid traits for hazards are not in CONFIG.PF2E, so we define them here.
	// Source: https://2e.aonprd.com/Rules.aspx?ID=522
	// Note: "complex" and "simple" are not really traits, but are often mis-entered as such.
	// Note: "environmental" is also not really a trait, but is used in some official content.
	// Note: "trap" and "haunt" are also not really traits, but are used in some official content.
	const validHazardTraits = new Set([
		"mechanical", "magical", "trap", "haunt", "environmental", "complex", "simple",
		"fire", "cold", "acid", "electricity", "poison", "mental", "shadow", "light",
		"arcane", "divine", "primal", "occult", "auditory", "visual", "linguistic", "emotion"
	]);

	const errors = [];

	// Check all actors for invalid traits
	for (const actor of game.actors.contents) {
		const traits = actor.system?.traits?.value ?? [];
		const type = actor.type;
		let validTraits;

		// Determine which set of valid traits to use based on actor type
		// Note: We only check hazards and creatures (NPCs, characters, familiars, and generic creatures).
		// Other actor types (e.g., vehicles, loot, ships) are skipped.
		// This is because they either don't have traits or have traits that are not well-defined.
		// If you want to check other actor types, you'll need to define their valid traits as well.
		if (type === "hazard") {
			// Use our defined hazard traits
			validTraits = validHazardTraits;
		} else if (["npc", "character", "familiar", "creature"].includes(type)) {
			// Use PF2e creature traits from CONFIG
			validTraits = new Set(Object.keys(CONFIG.PF2E.creatureTraits));
		} else {
			continue; // skip actors without a trait model we trust
		}

		// Find any traits that are not in the valid set
		const invalidTraits = traits.filter(t => !validTraits.has(t));
		// If any invalid traits are found, log a warning and add to errors list
		if (invalidTraits.length > 0) {
			console.log(`Invalid traits on [${actor.name}] (${actor.id})`, {
				type,
				traits,
				invalidTraits
			});
			errors.push({
				name: actor.name,
				id: actor.id,
				type,
				traits,
				invalidTraits
			});
		}
	}

	// Check all hazards in the compendium packs for invalid traits
	for (const pack of game.packs.contents) {
		if (pack.documentName !== "Actor" || !pack.metadata?.pf2e || !pack.metadata?.name?.toLowerCase().includes("hazard")) {
			continue; // skip non-Actor packs and non-PF2e hazard packs
		}
		await pack.getIndex(); // ensure index is loaded
		for (const entry of pack.index) {
			const hazard = await pack.getDocument(entry._id);
			const traits = hazard.system?.traits?.value ?? [];
			const type = hazard.type;
			const validTraits = validHazardTraits; // hazards always use our defined hazard traits
			// Find any traits that are not in the valid set
			const invalidTraits = traits.filter(t => !validTraits.has(t));
			// If any invalid traits are found, log a warning and add to errors list
			if (invalidTraits.length > 0) {
				console.log(`Invalid traits on [${hazard.name}] (${hazard.id}) in pack [${pack.metadata.label}]`, {
					type,
					traits,
					invalidTraits
				});
				errors.push({
					name: hazard.name,
					id: hazard.id,
					type,
					traits,
					invalidTraits
				});
			}
		}
	}

	// If no errors found, notify and exit
	if (errors.length === 0) {
		ui.notifications.info("✅ No invalid traits found on hazards or actors.");
		return;
	}

	// Show a dialog with the list of errors
	console.log("Invalid traits found on hazards or actors:", errors);
	ui.notifications.error(`Found ${errors.length} actor(s) or hazard(s) with invalid traits. See the dialog for details.`);
	// Build HTML list of errors
	const list = errors.map(e => `
		<li style="margin-bottom: 1em;">
			<strong>${e.name}</strong> (${e.id}) [<code>${e.type}</code>]<br>
			<div><strong>All Traits:</strong> ${e.traits.join(", ")}</div>
			<div style="color: red;"><strong>Invalid:</strong> ${e.invalidTraits.join(", ")}</div>
		</li>
	`).join("");
	// Show dialog
	new Dialog({
		title: "Invalid Trait Report",
		content: `
			<div style="max-height: 600px; overflow-y: auto;">
				<h2>Actors with Invalid Traits</h2>
				<ul>${list}</ul>
				<p><em>Check the console for full debug output.</em></p>
			</div>`,
		buttons: {
			ok: { label: "Close" }
		}
	}).render(true);
})();
